<template><main class="tr-service" :data-page="pageKey" data-testid="shopping-store-service-page"><header><button @click="emit('back')">←</button><strong>TRADERS <small>WHOLESALE CLUB</small></strong><button @click="emit('open-service')">MEMBER SERVICE</button></header><section v-if="pageKey==='checkout'" class="tr-review" data-testid="shopping-checkout-review"><header><div><span>LOAD REVIEW / MEMBER ACTIVE</span><h1>{{ l('在进入提货区前完成装载计划','Complete the load plan before entering the pickup dock') }}</h1></div><aside><b>{{ cartQuantity }}</b><span>CASES</span></aside></header><section class="tr-review-board"><div><span>PALLETS</span><b>{{ Math.max(1,Math.ceil(cartQuantity/6)) }}</b></div><div><span>VEHICLE</span><b>{{ cartQuantity>3?'VAN':'COMPACT SUV' }}</b></div><div><span>DOCK</span><b>SELECT AFTER ORDER</b></div></section><div class="tr-review-layout"><section><header><span>SKU</span><span>LOAD</span><span>VALUE</span></header><article v-for="(line,index) in cartItems" :key="line.productId"><b>T-{{ 6100+index }}</b><div><strong>{{ productDisplayTitle(line.product) }}</strong><small>{{ line.quantity }} CASE / 12 UNITS</small></div><em>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</em></article></section><aside><span>LOAD VALUE</span><strong>{{ cartTotalLabel }}</strong><p>{{ l('提货窗和搬运方式在订单创建后继续确认。','Pickup slot and handling continue after the order is created.') }}</p><em v-if="giftEnabled">BULK GIFT / {{ giftRecipientName||'RECIPIENT ATTACHED' }}</em><button data-testid="shopping-place-order" :disabled="!cartItems.length" @click="emit('place-order')">ISSUE PICKUP ORDER</button><button @click="emit('open-cart')">BACK TO TROLLEY</button></aside></div></section><section v-else class="tr-help" data-testid="shopping-service-page"><header><span>MEMBER SERVICE / WAREHOUSE</span><h1>{{ l('按整箱、装载和提货处理','Support by case, load, and pickup') }}</h1></header><div class="tr-help-board"><article><span>A01</span><i class="